import { toast } from "~/components/ui/toast"
import i18n from "~/i18n"

// The service worker (generated by scripts/generate-sw.ts) serves the app shell from cache. A new
// build installs in the background and waits; it takes over only when the user reloads through
// reloadToLatest(), so an open reply stream is never cut off by a deploy.
const supported = import.meta.env.PROD && typeof window !== "undefined" && "serviceWorker" in navigator

let switching = false
let prompted = false

function waitForInstall(worker: ServiceWorker) {
  return new Promise<void>((resolve) => {
    if (worker.state !== "installing") return resolve()
    worker.addEventListener("statechange", () => {
      if (worker.state !== "installing") resolve()
    })
  })
}

/** Reloads into the newest deployed build, activating a waiting service worker first. */
export async function reloadToLatest() {
  const registration = supported ? await navigator.serviceWorker.getRegistration() : undefined
  await registration?.update().catch(() => undefined)
  const pending = registration?.installing ?? registration?.waiting
  if (pending) await waitForInstall(pending)
  const waiting = registration?.waiting
  if (waiting && navigator.serviceWorker.controller) {
    // The controllerchange listener reloads once the new worker is in charge.
    switching = true
    waiting.postMessage({ type: "SKIP_WAITING" })
    return
  }
  window.location.reload()
}

function promptUpdate() {
  if (prompted) return
  prompted = true
  toast.add({
    title: i18n.t("common.updateAvailable"),
    timeout: 0,
    actionProps: { children: i18n.t("common.actions.reload"), onClick: () => void reloadToLatest() },
  })
}

async function register() {
  const registration = await navigator.serviceWorker.register("/sw.js")
  // Without a controller this is the first install, not an update.
  if (registration.waiting && navigator.serviceWorker.controller) promptUpdate()
  registration.addEventListener("updatefound", () => {
    const worker = registration.installing
    worker?.addEventListener("statechange", () => {
      if (worker.state === "installed" && navigator.serviceWorker.controller) promptUpdate()
    })
  })
  // An installed app can stay open for days; check for a new build whenever it comes back into view.
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") void registration.update().catch(() => undefined)
  })
}

if (supported) {
  navigator.serviceWorker.addEventListener("controllerchange", () => {
    if (switching) window.location.reload()
  })
  if (document.readyState === "complete") void register()
  else window.addEventListener("load", () => void register(), { once: true })
}
